package mandelbrot

import fpgalib._

import spinal.core._
import spinal.lib._
import spinal.lib.bus.amba4.axi._
import spinal.lib.bus.amba4.axilite._

// =====================================================================================================
// sys_pll is generated by quartus/Makefile; the Terasic IP BlackBoxes are in fpgalib (De25NanoIp.scala).
// =====================================================================================================

/** IOPLL generated by quartus/Makefile (ip-deploy altera_iopll): outclk_0 = pixel clock,
  * outclk_1 = core clock.
  */
class sys_pll extends BlackBox {
  val refclk   = in Bool ()
  val rst      = in Bool ()
  val outclk_0 = out Bool ()
  val outclk_1 = out Bool ()
  val locked   = out Bool ()
}

// =====================================================================================================
// Top level
// =====================================================================================================

/** DE25-Nano top level (replaces top.sv). Port names are those of Terasic's golden_top, so the pin
  * assignments of golden_top.qsf apply unchanged.
  *
  * Clocks:
  *   CLOCK0_50 -> sys_pll -> pixel clock (148.5 MHz), core clock (cfg.coreHz)
  *   CLOCK1_50 -> EMIF_Qsys IOPLL -> 310 MHz AXI clock (memory domain), AXI-Lite clock
  *
  * KEY[0]: render again, KEY[1]: reset (both active low).
  * LED (on = low): 0 memory calibrated and HDMI set up, 1 HDMI setup error, 2 underrun in the last
  *   frame, 3 render pending, 5 memory calibration failed, 7 heartbeat.
  */
class De25NanoTop(cfg: SystemConfig = SystemConfig()) extends Component {
  val io = new Bundle {
    val CLOCK0_50, CLOCK1_50 = in Bool ()
    val KEY = in Bits (2 bits)
    val LED = out Bits (8 bits)

    val HDMI_TX_CLK  = out Bool ()
    val HDMI_TX_HS   = out Bool ()
    val HDMI_TX_VS   = out Bool ()
    val HDMI_TX_DE   = out Bool ()
    val HDMI_TX_D    = out Bits (24 bits)
    val HDMI_I2C_SCL = inout(Analog(Bool()))
    val HDMI_I2C_SDA = inout(Analog(Bool()))
    val HDMI_TX_INT  = in Bool ()

    val FPGA_UART_TX = out Bool ()
    val FPGA_UART_RX = in Bool ()

    val LPDDR4A = Lpddr4Pins()
    val LPDDR4B = Lpddr4Pins()
  }
  noIoPrefix()
  io.LPDDR4A.setName("LPDDR4A")
  io.LPDDR4B.setName("LPDDR4B")

  // ---------------------------------------------------------------------------------- reset + clocks
  val resetRelease = new agilex_reset_release
  val initDone     = !resetRelease.ninit_done

  val pll = new sys_pll
  pll.refclk := io.CLOCK0_50
  pll.rst    := !initDone

  val emif = new EMIF_Qsys
  emif.iopll_refclk_clk  := io.CLOCK1_50
  emif.iopll_reset_reset := !initDone
  val emifReset_n = emif.iopll_locked_export && initDone
  emif.reset_reset_n := emifReset_n

  val keyReset = !io.KEY(1)

  /** Reset asserted asynchronously, released synchronously to `clk`. */
  def syncReset(clk: Bool, rst: Bool): Bool = {
    val cd = ClockDomain(clk, config = ClockDomainConfig(resetKind = BOOT))
    ResetCtrl.asyncAssertSyncDeassert(rst, cd, inputPolarity = HIGH, outputPolarity = HIGH, bufferDepth = Some(3))
  }
  val coreClk = pll.outclk_1
  val pixClk  = pll.outclk_0
  val memClk  = emif.clock_310m_out_clk_clk
  val axilClk = emif.iopll_outclk_axi4_lite_clk

  val coreRst = syncReset(coreClk, !pll.locked || !initDone || keyReset)
  val pixRst  = syncReset(pixClk, !pll.locked || !initDone)
  val memRst  = syncReset(memClk, !emif.a.ctrlReady || !emifReset_n)

  // ---------------------------------------------------------------------------------- memory
  emif.a.connectPins(io.LPDDR4A)
  emif.b.connectPins(io.LPDDR4B)

  val axilCd = ClockDomain(axilClk, emifReset_n, config = ClockDomainConfig(resetKind = ASYNC, resetActiveLevel = LOW))
  for (ch <- Seq(emif.a, emif.b)) {
    ch.axilClk  := axilClk
    ch.axilRstN := emifReset_n
  }
  val calA = axilCd(new EmifCalibration)
  val calB = axilCd(new EmifCalibration)
  calA.io.axil >> emif.a.axil
  calB.io.axil >> emif.b.axil

  // Bank B isn't used (it has to be calibrated because it shares the Platform Designer system).
  emif.b.axi.ar.valid := False
  emif.b.axi.ar.payload.assignDontCare()
  emif.b.axi.aw.valid := False
  emif.b.axi.aw.payload.assignDontCare()
  emif.b.axi.w.valid  := False
  emif.b.axi.w.payload.assignDontCare()
  emif.b.axi.r.ready  := True
  emif.b.axi.b.ready  := True

  // ---------------------------------------------------------------------------------- the design
  val sys = new MandelbrotSystem(cfg)
  sys.io.coreClk := coreClk
  sys.io.coreRst := coreRst
  sys.io.memClk  := memClk
  sys.io.memRst  := memRst
  sys.io.pixClk  := pixClk
  sys.io.pixRst  := pixRst

  sys.io.axi >> emif.a.axi

  sys.io.memCalibrated := calA.io.done
  sys.io.renderKey     := !io.KEY(0)

  io.HDMI_TX_CLK := pixClk
  io.HDMI_TX_D   := sys.io.hdmi.r ## sys.io.hdmi.g ## sys.io.hdmi.b
  io.HDMI_TX_HS  := sys.io.hdmi.hsync
  io.HDMI_TX_VS  := sys.io.hdmi.vsync
  io.HDMI_TX_DE  := sys.io.hdmi.de
  sys.io.hdmi.interrupt := io.HDMI_TX_INT

  // open drain: drive low or release (the board has pull-ups)
  when(sys.io.hdmi.scl.drive) { io.HDMI_I2C_SCL := False }
  when(sys.io.hdmi.sda.drive) { io.HDMI_I2C_SDA := False }
  sys.io.hdmi.scl.read := io.HDMI_I2C_SCL
  sys.io.hdmi.sda.read := io.HDMI_I2C_SDA

  io.FPGA_UART_TX     := sys.io.uart.txd
  sys.io.uart.rxd     := io.FPGA_UART_RX

  io.LED := ~(sys.io.leds | (B"00" ## calA.io.failed ## B"00000"))
}
